using Microsoft.EntityFrameworkCore;
class MigrationRunner
{
    // EF Core 9 breaking change: Migrate() can no longer be called inside a
    // manual transaction — it now manages its own transaction internally.
    void ApplyMigrations(AppDbContext db)
    {
        var strategy = db.Database.CreateExecutionStrategy();
        strategy.Execute(() =>
        {
            db.Database.Migrate();
        });
    }

    // EF Core 9 breaking change: Cosmos DB provider no longer supports
    // synchronous queries. Must use async methods.
    // BEFORE (broken in EF Core 9):
    //   var products = cosmosDb.Products.ToList();
    // AFTER:
    async Task QueryCosmosAsync(CosmosDbContext cosmosDb)
    {
        var products = await cosmosDb.Products.ToListAsync();
    }
}

